//! The web console under `/ui/` (docs/web-ui.md): the client built into
//! the binary, served from the same origin as the API. Every console path
//! that is not a file answers the client's `index.html`, so a deep link
//! reloads to the same screen; API routes are never answered with a page.

use axum::Router;
use axum::extract::Path;
use axum::http::{HeaderValue, StatusCode, header};
use axum::response::{IntoResponse, Redirect, Response};
use axum::routing::get;

/// One file of the built client.
struct Asset {
    path: &'static str,
    bytes: &'static [u8],
}

/// Generated by `build.rs` from `web/dist` (or `SACI_WEB_DIST`); empty
/// when the console was not built.
static ASSETS: &[Asset] = include!(concat!(env!("OUT_DIR"), "/console_assets.rs"));

/// The base path of the console.
pub const UI_BASE: &str = "/ui";

const CSP: &str = "default-src 'self'; script-src 'self'; style-src 'self'; \
    img-src 'self' data:; font-src 'self'; connect-src 'self'; object-src 'none'; \
    base-uri 'none'; form-action 'self'; frame-ancestors 'none'";

const PLACEHOLDER: &str = "<!doctype html>
<html lang=\"en\"><head><meta charset=\"utf-8\"><title>Midnight Saci</title></head>
<body><h1>The web console is not built into this backend</h1>
<p>Build it with <code>make console</code>, or run <code>npm run dev</code> in
<code>web/</code> against this backend; see docs/web-ui.md. The REST API is
available under <code>/api/v1</code>.</p></body></html>
";

/// Whether this binary carries the built console.
#[must_use]
pub fn embedded() -> bool {
    !ASSETS.is_empty()
}

/// `/` and `/ui` redirect to `/ui/`; `/ui/…` serves the console.
pub fn routes() -> Router {
    Router::new()
        .route("/", get(|| async { Redirect::to("/ui/") }))
        .route(UI_BASE, get(|| async { Redirect::to("/ui/") }))
        .route("/ui/", get(index))
        .route("/ui/{*path}", get(file))
}

fn find(path: &str) -> Option<&'static Asset> {
    ASSETS.iter().find(|asset| asset.path == path)
}

fn content_type(path: &str) -> &'static str {
    let extension = path.rsplit_once('.').map_or("", |(_, extension)| extension);
    match extension {
        "html" => "text/html; charset=utf-8",
        "js" => "text/javascript; charset=utf-8",
        "css" => "text/css; charset=utf-8",
        "json" => "application/json",
        "svg" => "image/svg+xml",
        "png" => "image/png",
        "ico" => "image/x-icon",
        "woff2" => "font/woff2",
        "woff" => "font/woff",
        "txt" => "text/plain; charset=utf-8",
        _ => "application/octet-stream",
    }
}

fn respond(
    status: StatusCode,
    kind: &'static str,
    cache: &'static str,
    body: &'static [u8],
) -> Response {
    let mut response = (status, body).into_response();
    let headers = response.headers_mut();
    headers.insert(header::CONTENT_TYPE, HeaderValue::from_static(kind));
    headers.insert(header::CACHE_CONTROL, HeaderValue::from_static(cache));
    headers.insert(
        header::X_CONTENT_TYPE_OPTIONS,
        HeaderValue::from_static("nosniff"),
    );
    headers.insert(
        header::REFERRER_POLICY,
        HeaderValue::from_static("no-referrer"),
    );
    headers.insert(header::X_FRAME_OPTIONS, HeaderValue::from_static("DENY"));
    headers.insert(
        header::CONTENT_SECURITY_POLICY,
        HeaderValue::from_static(CSP),
    );
    response
}

async fn index() -> Response {
    find("index.html").map_or_else(
        || {
            respond(
                StatusCode::OK,
                "text/html; charset=utf-8",
                "no-cache",
                PLACEHOLDER.as_bytes(),
            )
        },
        |asset| {
            respond(
                StatusCode::OK,
                content_type(asset.path),
                "no-cache",
                asset.bytes,
            )
        },
    )
}

async fn file(Path(path): Path<String>) -> Response {
    if let Some(asset) = find(&path) {
        // Vite names everything under assets/ by content hash.
        let cache = if path.starts_with("assets/") {
            "public, max-age=31536000, immutable"
        } else {
            "no-cache"
        };
        return respond(StatusCode::OK, content_type(asset.path), cache, asset.bytes);
    }
    let looks_like_file = path
        .rsplit('/')
        .next()
        .is_some_and(|name| name.contains('.'));
    if path.starts_with("assets/") || looks_like_file {
        return respond(
            StatusCode::NOT_FOUND,
            "text/plain; charset=utf-8",
            "no-cache",
            b"not found\n",
        );
    }
    index().await
}
